content:
{
 "kind": "sequence",
 "format": 1,
 "id": "seq_cphl_booth_break",
 "name": "Cluster Puck: the booth, the period in review",
 "set": "set_slush_booth",
 "roles": {
  "pbp": {
   "mark": "pbp",
   "label": "Play-by-play"
  },
  "col": {
   "mark": "col",
   "label": "Colour"
  }
 },
 "wall": "feed",
 "wallText": "{venue}",
 "wallSub": "{show}",
 "beats": [
  {
   "id": "b1",
   "shot": {
    "cam": "wide",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "drift",
    "cut": "dissolve"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "That's the {section}. {away} {awayScore}, {home} {homeScore}.",
     "Horn goes on the {section}. {away} {awayScore}, {home} {homeScore}."
    ]
   },
   "gfx": [
    {
     "kind": "score",
     "title": "{status}",
     "left": "{away}",
     "leftScore": "{awayScore}",
     "right": "{home}",
     "rightScore": "{homeScore}",
     "sub": "{venue}",
     "at": 0.2,
     "for": 0
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "b2",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "I'm {pbp.name}, with {col.name}. Let's look at the period.",
     "{pbp.name} here with {col.name}. Here's how that period went."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{pbp.name}",
     "sub": "Play-by-play",
     "at": 0.4,
     "for": 4.5
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "b3",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{periodGoalsSaid} in that one. Here's how they went in.",
     "{periodGoalsSaid} that period. Let's go through them."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{col.name}",
     "sub": "Colour",
     "at": 0.4,
     "for": 4.5
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "periodGoalCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b4",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "Nothing on the board that period. {periodShots} shots and nobody got one in.",
     "No goals in the {section}. Both goalies were good."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{col.name}",
     "sub": "Colour",
     "at": 0.4,
     "for": 4.5
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "periodGoalCount",
     "op": "=",
     "value": "0"
    }
   ]
  },
  {
   "id": "g_goal",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{player} for {team}, with {clock} left in the {period}.",
     "{player} scores for {team}. {clock} to go in the {period}.",
     "{player} {strengthSaid}, with {clock} left."
    ]
   },
   "gfx": [
    {
     "kind": "box",
     "source": "feed",
     "title": "REPLAY",
     "side": "right",
     "at": 0,
     "for": 0
    },
    {
     "kind": "lower",
     "text": "{player}",
     "sub": "{team} · {period} {clock}",
     "at": 0.6,
     "for": 0
    }
   ],
   "each": "periodGoals",
   "eachMax": 8,
   "roll": "{reel}"
  },
  {
   "id": "b5",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "push",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "Shots in the period: {periodShotsAway} for {away}, {periodShotsHome} for {home}.",
     "{away} had {periodShotsAway} shots in the {section}. {home} had {periodShotsHome}."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "SHOTS · {section}",
     "rows": [
      "{away}: {periodShotsAway}",
      "{home}: {periodShotsHome}"
     ],
     "side": "left",
     "at": 0.3,
     "for": 0
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ]
  },
  {
   "id": "b6",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{periodPenaltiesSaid} called in the {section}.",
     "The ref called {periodPenaltiesSaid} that period."
    ]
   },
   "gfx": [
    {
     "kind": "table",
     "title": "PENALTIES · {section}",
     "list": "periodPenalties",
     "row": "{player}: {infraction}, {minutes} min",
     "limit": 6,
     "side": "left",
     "at": 0.3,
     "for": 0
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "periodPenaltyCount",
     "op": ">",
     "value": 0
    }
   ]
  },
  {
   "id": "b7",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{winner} and {loser} dropped the gloves. {winner} won that one.",
     "{winner} fought {loser}, and {loser} came off worse."
    ]
   },
   "gfx": [
    {
     "kind": "lower",
     "text": "{winner}",
     "sub": "Won the fight",
     "at": 0.4,
     "for": 4.5
    },
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "each": "periodFights",
   "eachMax": 3,
   "if": [
    {
     "fact": "winner",
     "op": "has"
    },
    {
     "fact": "loser",
     "op": "has"
    }
   ]
  },
  {
   "id": "b8",
   "shot": {
    "cam": "cam1",
    "frame": "medium",
    "on": [
     "pbp"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "{player} went off hurt. Here's the hit.",
     "{player} of {team} got hurt. Look at this."
    ]
   },
   "gfx": [
    {
     "kind": "box",
     "source": "feed",
     "title": "REPLAY",
     "side": "right",
     "at": 0,
     "for": 0
    },
    {
     "kind": "lower",
     "text": "{player}",
     "sub": "{team} · Injured",
     "at": 0.6,
     "for": 0
    }
   ],
   "each": "periodInjuries",
   "eachMax": 4,
   "roll": "{reel}",
   "if": [
    {
     "fact": "player",
     "op": "has"
    }
   ]
  },
  {
   "id": "b9",
   "shot": {
    "cam": "cam3",
    "frame": "medium",
    "on": [
     "col"
    ],
    "move": "none",
    "cut": "cut"
   },
   "say": {
    "role": "col",
    "lines": [
     "{periodHits} hits along the boards that period. Nobody is taking it easy.",
     "{periodHits} big hits in the {section}. They're going to feel that tomorrow."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "periodHits",
     "op": ">=",
     "value": 4
    }
   ]
  },
  {
   "id": "b10",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "The Zamboni's out. We'll go to the desk, and we're back for the {nextOrd}.",
     "Let's head to the studio while they do the ice. Back for the {nextOrd} after this."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "section",
     "op": "!=",
     "value": "3rd"
    }
   ]
  },
  {
   "id": "b11",
   "shot": {
    "cam": "cam1",
    "frame": "two",
    "on": [
     "pbp",
     "col"
    ],
    "move": "pull",
    "cut": "cut"
   },
   "say": {
    "role": "pbp",
    "lines": [
     "Tied after sixty minutes. We'll go to the desk, and then it's overtime.",
     "Sixty minutes and nothing settled. Over to the desk, and we'll be back for overtime."
    ]
   },
   "gfx": [
    {
     "kind": "pip",
     "source": "feed",
     "title": "LIVE · THE ICE",
     "corner": "top-right",
     "at": 0.3,
     "for": 0
    }
   ],
   "if": [
    {
     "fact": "section",
     "op": "=",
     "value": "3rd"
    }
   ]
  }
 ]
}
